import json, os
WP = "https://www.whoprofits.org/companies/company/"
AF = "https://investigate.afsc.org/company/"
BDS = "https://bdsmovement.net/Guide-to-BDS-Boycott"
R = {}
def ex(t, label, cat, text, *src): R.setdefault(t, {"verdict": "EXCLUDE", "findings": []})["findings"].append({"label": label, "category": cat, "text": text, "sources": list(src)})
def ok(t, note="No documented or campaign-targeted involvement found in AFSC Investigate, Who Profits, or the BDS target guide; targeted web search found none.", flags=()):
    R[t] = {"verdict": "PASS", "note": note, "findings": [{"label": "c", "category": c, "text": x, "sources": list(s)} for c, x, s in flags]}
# --- exclusions ---
ex("NVDA","a","Military supplier (Israel)","AFSC Investigate: Israeli Ministry of Defense disclosed purchases of Nvidia Jetson and DGX products in 2023-2025; Jetson used in Elbit Lanius drone.", AF+"nvidia")
ex("AMD","a","Defense supply chain (military-grade parts)","AMD markets a dedicated defense-grade XQ FPGA/SoC line (MIL-STD-883, -55 to 125C) for aerospace and defense.", "https://www.amd.com/en/products/adaptive-socs-and-fpgas/versal/defense-grade.html","https://www.amd.com/content/dam/amd/en/documents/products/adaptive-socs-and-fpgas/product-briefs/xq-ultrascale-aerospace-defense-product-brief.pdf")
ex("TXN","a","Defense supply chain (military-grade parts)","TI sells QML Class Q military-grade and Enhanced Products for aerospace and defense; described as a leading QML supplier to the US military.", "https://ti.com/ep","https://www.ti.com/quality-reliability/certifications-standards/part-ratings.html")
ex("AVGO","a","Defense supply chain (military-grade parts)","Broadcom markets hermetic optocouplers 'for use in military applications' with MIL-PRF-38534 Class H/K testing and DLA SMD part numbers.", "https://www.broadcom.com/pages/en/optocouplers_hermetic/hermetic_power_mosfet/hssr-7111200/","https://docs.broadcom.com/doc/AV02-3840EN")
ex("MU","a","Defense supply chain (military-grade parts)","Micron launched a radiation-tolerant/space-qualified memory portfolio for aerospace and defense and partners with defense electronics maker Mercury Systems.", "https://www.eejournal.com/industry_news/micron-launches-space-qualified-portfolio-to-power-mission-critical-data-for-aerospace-innovation/","https://mrcy.com/capabilities/strategic-relationships/Micron")
ex("XOM","a","Military supplier (Israel)","AFSC Investigate: supplies jet fuel used by the Israeli air force.", AF+"exxon-mobil")
ex("KO","a","Occupation (settlements)","AFSC Investigate: Israeli licensee (Central Bottling Co.) operates a logistics center in an illegal West Bank settlement; also listed in Who Profits.", AF+"coca-cola", WP+"4081?the-central-bottling-company-cbc-coca-cola-israel")
ex("KO","b","Campaign-targeted","BDS 'organic boycott target'.", BDS)
ex("CVX","b","Campaign-targeted (occupation/energy)","BDS consumer-boycott priority target and AFSC 'BDS Divestment Shortlist': main extractor of gas claimed by Israel.", BDS, AF+"chevron")
ex("CSCO","a","Military/police supplier + settlements","Who Profits and AFSC: provides servers, communications and cybersecurity to the Israeli military, IMOD and police, and surveillance/comms to settlements.", WP+"6529?cisco-systems", AF+"cisco")
ex("INTC","a","Military supplier (Israel) / US DoD","AFSC: provides products and services to the Israeli military; DoD RAMP-C chip program award.", AF+"intel", "https://www.theregister.com/2021/08/24/intel_qualcomm_ramp_c/")
ex("INTC","b","Campaign-targeted","BDS divestment target over $25B Kiryat Gat investment.", BDS)
ex("SAP","a","Military software to defense ministries","SAP Israel contracted to supply ERP to the IDF and Israeli MoD; SAP National Security Services awarded a $1B US Army contract (2025).", "https://www.ynetnews.com/articles/0,7340,L-4176779,00.html","https://www.itiger.com/news/2570042383")
ex("CRM","a","Military software to defense ministries","US Army awarded Salesforce (via its national-security unit Missionforce) a $5.6B 10-year IDIQ contract (Jan 2026).", "https://investor.salesforce.com/news/news-details/2026/U-S--Army-Awards-Salesforce-5-6B-Contract-to-Accelerate-Military-Modernization-and-Department-of-War-Readiness","https://defensescoop.com/2026/01/26/salesforce-army-contract-data-analytics-cloud-agentic-ai/")
ex("PANW","a","Military software to defense ministries","Multi-year DoD contracts (Cortex Xpanse; DoD ESI award; reported ~$1B five-year software deal).", "https://www.paloaltonetworks.com/security-for/government/federal","https://news.streetbeat.com/article/41653144")
ex("CRWD","a","Military software to defense ministries","Dedicated 'CrowdStrike for Department of War' offering; IL5 authorization from the US defense department.", "https://www.crowdstrike.com/en-us/solutions/department-of-war/","https://crowdstrike.com/department-of-defense")
ex("QCOM","a","Military contracts (DoD)","DoD RAMP-C secure chip program (with Intel), DISA authentication pilot contract, US Navy 5G/AI research agreement.", "https://www.qualcomm.com/news/releases/2018/01/department-defense-awards-innovative-contract-qualcomm-pilot-actionless","https://www.theregister.com/2021/08/24/intel_qualcomm_ramp_c/","https://insidetowers.com/2023/02/15/page/2")
ex("ANET","a","Military networking sold to DoD","Platforms certified on DoD Unified Capabilities Approved Products List; resellers state Arista is deployed across DoD and the Intelligence Community.", "https://www.arista.com/en/company/news/press-release/2142-pr-20170207","https://www.dlt.com/government-products/arista-federal")
ex("TMO","a","Mass surveillance (DNA)","HRW documented Thermo Fisher sequencers/kits used in mass DNA collection by police in Xinjiang (sales halted 2019) and Tibet (halted Jan 2024); HRW says sales to Chinese police continue elsewhere.", "https://www.hrw.org/news/2024/01/30/us-company-must-stop-supplying-chinas-regime-dna-surveillance-tech","https://theintercept.com/2022/09/13/china-tibet-police-dna-thermo-fisher/","https://www.axios.com/2024/01/03/tibet-thermo-fisher-halts-dna-collection-kit-sales")
# --- passes ---
ok("AAPL", flags=[("Forced labor (supply chain)","ASPI 'Uyghurs for Sale' (2020) traced Uyghur labour transfers to factories in Apple's supply chain; Apple disputes. Indirect -> flagged, not excluded.",["https://venturebeat.com/business/apple-foxconn-and-81-others-are-accused-of-using-uighur-forced-labor"])])
ok("TSLA", flags=[("Forced labor (supply chain)","Sheffield Hallam 'Driving Force' (2022) lists Tesla among automakers with supply-chain exposure to Uyghur-region forced labour. Indirect -> flagged.",["https://www.business-humanrights.org/en/latest-news/report-driving-force-automotive-supply-chains-and-forced-labor-in-the-uyghur-region/"])])
ok("TSM", flags=[("Dual-use diversion","TSMC-made chips have been reported in Russian weapons via third-party diversion; no direct military supply found. Flagged.",[])])
ok("GEV", note="Not listed itself. Who Profits lists the predecessor General Electric (now GE Aerospace, ticker GE) for military engines; GE Vernova (power/grid, spun off 2024) is a separate company.", flags=[("Legacy GE link","Who Profits entry concerns GE Aerospace's military engines, not GE Vernova. Flagged for awareness.",[WP+"6337?general-electric"])])
ok("SHOP", flags=[("Boycott (unrelated to involvement)","A 2025 consumer boycott over an executive's social-media post on Israel coverage; not involvement in occupation/military. Flagged only.",["https://jewishinsider.com/2025/03/augustus-media-shopify-harley-finkelstein-israel-gaza/"])])
for t in "LLY V JNJ MA ASML PG MRK HD NVS AZN AMAT LRCX LIN GILD BHP KLAC ARM ABT NVO UNP WELL DHR".split(): ok(t)
db = json.load(open("ethics.json")) if os.path.exists("ethics.json") else {}
for t, v in R.items(): v["batch"] = 1; v["review"] = "manual"; db[t] = v
json.dump(db, open("ethics.json","w"), indent=1)
print(len(R), sum(v["verdict"]=="PASS" for v in R.values()))
